using System; using System.IO; using System.Diagnostics; using System.Runtime.InteropServices; using System.Text;
class Probe {
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)] struct STARTUP {public int cb;public string reserved,desktop,title;public int x,y,xSize,ySize,xCount,yCount,fill,flags;public short show,cbReserved;public IntPtr lpReserved,input,output,error;}
 [StructLayout(LayoutKind.Sequential)] struct PROCESS {public IntPtr process,thread;public uint pid,tid;}
 [StructLayout(LayoutKind.Explicit,Size=176)] struct EVENT {[FieldOffset(0)]public uint code;[FieldOffset(4)]public uint pid;[FieldOffset(8)]public uint tid;[FieldOffset(16)]public IntPtr data;[FieldOffset(24)]public IntPtr process;[FieldOffset(24)]public ushort unicode;[FieldOffset(26)]public ushort length;[FieldOffset(16)]public uint exception;[FieldOffset(32)]public IntPtr address;[FieldOffset(168)]public uint first;}
 [DllImport("kernel32",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool CreateProcess(string app,StringBuilder cmd,IntPtr pa,IntPtr ta,bool inherit,uint flags,IntPtr env,string cwd,ref STARTUP si,out PROCESS pi);
 [DllImport("kernel32",SetLastError=true)]static extern bool WaitForDebugEvent(out EVENT e,uint timeout);
 [DllImport("kernel32")]static extern bool ContinueDebugEvent(uint pid,uint tid,uint status);
 [DllImport("kernel32")]static extern bool ReadProcessMemory(IntPtr p,IntPtr a,byte[] data,IntPtr size,out IntPtr read);
 [DllImport("kernel32")]static extern bool TerminateProcess(IntPtr p,uint exitCode);
 [DllImport("kernel32")]static extern bool CloseHandle(IntPtr h);
 [DllImport("Dbghelp.dll",SetLastError=true)]static extern bool MiniDumpWriteDump(IntPtr process,uint pid,IntPtr file,uint type,IntPtr exception,IntPtr stream,IntPtr callback);
 static int Main(string[] args){var si=new STARTUP();si.cb=Marshal.SizeOf(si);PROCESS pi;string exe=Path.GetFullPath(args[0]);if(!CreateProcess(exe,new StringBuilder("\""+exe+"\" --enable-logging=stderr"),IntPtr.Zero,IntPtr.Zero,false,0x08000002,IntPtr.Zero,Path.GetDirectoryName(exe),ref si,out pi)){Console.WriteLine("CreateProcess error "+Marshal.GetLastWin32Error());return 1;}var timer=Stopwatch.StartNew();bool initial=false;while(timer.ElapsedMilliseconds<10000){EVENT e;if(!WaitForDebugEvent(out e,1000))continue;uint status=0x00010002;if(e.code==8){var bytes=new byte[e.length* (e.unicode!=0?2:1)];IntPtr read;if(ReadProcessMemory(pi.process,e.data,bytes,(IntPtr)bytes.Length,out read))Console.WriteLine((e.unicode!=0?Encoding.Unicode:Encoding.Default).GetString(bytes).TrimEnd('\0'));}if(e.code==1){Console.WriteLine("Exception "+e.exception.ToString("X8")+" at "+e.address.ToString("X")+" first="+e.first);if(e.exception==0x80000003&&!initial)initial=true;else {status=0x80010001;if(e.first==0){string dump=Path.GetFullPath(args[1]);using(var f=new FileStream(dump,FileMode.Create,FileAccess.ReadWrite,FileShare.None))Console.WriteLine("Dump captured="+MiniDumpWriteDump(pi.process,pi.pid,f.SafeFileHandle.DangerousGetHandle(),0,IntPtr.Zero,IntPtr.Zero,IntPtr.Zero)+" error="+Marshal.GetLastWin32Error()+" path="+dump);}}}if(e.code==5){ContinueDebugEvent(e.pid,e.tid,status);break;}ContinueDebugEvent(e.pid,e.tid,status);}TerminateProcess(pi.process,1);CloseHandle(pi.thread);CloseHandle(pi.process);return 0;}
}
